package com.bank.statement;

import java.util.logging.*;

public class IntersectionDemo {
    private static final Logger log = Logger.getLogger(IntersectionDemo.class.getName());

    static {
        LogManager.getLogManager().reset();
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        log.addHandler(handler);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        // Shared joint-account tail: J1 -> J2
        StatementNode j1 = new StatementNode("JOINT-1");
        StatementNode j2 = new StatementNode("JOINT-2");
        j1.next = j2;

        // Rajesh's longer personal chain: R1 -> R2 -> R3 -> (J1 -> J2)
        StatementNode rajesh = new StatementNode("RAJESH-1");
        rajesh.next = new StatementNode("RAJESH-2");
        rajesh.next.next = new StatementNode("RAJESH-3");
        rajesh.next.next.next = j1;

        // Priya's shorter personal chain: P1 -> (J1 -> J2)
        StatementNode priya = new StatementNode("PRIYA-1");
        priya.next = j1;

        log.info("Finding where Rajesh and Priya statement chains merge into the joint chain");
        IntersectionFinder finder = new IntersectionFinder();
        StatementNode junction = finder.findIntersection(rajesh, priya);

        if (junction != null) {
            log.info("Intersection node found -> " + junction.statementId);
        } else {
            log.warning("No intersection found between the two chains");
        }
    }
}

