class StatementNode {
    String statementId;
    StatementNode next;

    StatementNode(String statementId) {
        this.statementId = statementId;
    }
}

// ─── Would be in service/IntersectionFinder.java ───
class IntersectionFinder {
    // Two-pointer switching. O(n+m) time, O(1) space.
    StatementNode findIntersection(StatementNode headA, StatementNode headB) {
        if (headA == null || headB == null) return null;

        StatementNode pa = headA;
        StatementNode pb = headB;

        // Each pointer walks A+B total; they meet at the junction or both hit null
        while (pa != pb) {                       // identity comparison, not value
            pa = (pa == null) ? headB : pa.next; // switch A -> B at the end
            pb = (pb == null) ? headA : pb.next; // switch B -> A at the end
        }
        return pa;  // intersection node, or null if no intersection
    }
}

